import javax.swing.*;import javax.swing.filechooser.FileNameExtensionFilter;import java.awt.*;import java.io.File;
public class CompanyDetailsPanel extends JPanel {private final JTextField name=new JTextField(24),logo=new JTextField(24),companyPan=new JTextField(24),companyTan=new JTextField(24),employeeIdPrefix=new JTextField(24);private final JTextArea address=new JTextArea(4,24);public CompanyDetailsPanel(){setLayout(new GridBagLayout());GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(7,7,7,7);c.fill=GridBagConstraints.HORIZONTAL;name.setText(CompanyDetailsStore.name());address.setText(CompanyDetailsStore.address());address.setEditable(false);address.setEnabled(false);logo.setText(CompanyDetailsStore.logoPath());companyPan.setText(CompanyDetailsStore.pan());companyTan.setText(CompanyDetailsStore.tan());employeeIdPrefix.setText(CompanyDetailsStore.employeeIdPrefix());row(c,0,"Company Name",name);c.gridx=0;c.gridy=1;add(new JLabel("Company Address"),c);c.gridx=1;add(new JScrollPane(address),c);row(c,2,"Company PAN",companyPan);row(c,3,"Company TAN",companyTan);row(c,4,"Employee ID Prefix",employeeIdPrefix);JButton browse=new JButton("Upload Logo");browse.addActionListener(e->selectLogo());JPanel logoRow=new JPanel(new BorderLayout(6,0));logoRow.add(logo,BorderLayout.CENTER);logoRow.add(browse,BorderLayout.EAST);row(c,5,"Company Logo Path",logoRow);JButton save=new JButton("Save Company Details");save.addActionListener(e->save());c.gridx=1;c.gridy=6;add(save,c);}private void row(GridBagConstraints c,int row,String label,JComponent value){c.gridx=0;c.gridy=row;add(new JLabel(label),c);c.gridx=1;add(value,c);}private void selectLogo(){JFileChooser chooser=new JFileChooser();chooser.setFileFilter(new FileNameExtensionFilter("Image files","jpg","jpeg","png"));if(chooser.showOpenDialog(this)==JFileChooser.APPROVE_OPTION)logo.setText(chooser.getSelectedFile().getAbsolutePath());}private void save(){CompanyDetailsStore.name(name.getText().trim());CompanyDetailsStore.address(address.getText().trim());CompanyDetailsStore.pan(companyPan.getText().trim());CompanyDetailsStore.tan(companyTan.getText().trim());CompanyDetailsStore.employeeIdPrefix(employeeIdPrefix.getText());CompanyDetailsStore.logoPath(logo.getText().trim());JOptionPane.showMessageDialog(this,"Company details saved.");}}
